    func add<Key: Comparable, Value: CustomStringConvertible>(
      _ dict: [Key: Value]
    ) {
      if dict.isEmpty {
        return
      }

      result.append(
        contentsOf: dict.sorted { $0.key < $1 $1.key }
          .map { $0.value.description }
          .joined(separator: "\n")
      )

      result += "\n"
    }

